            c0, c1 = divider_cols[0] + 1, divider_cols[1]
        else:
            c0, c1 = 0, divider_cols[0]
    else:
        c0, c1 = 0, w
    if divider_rows:
        if len(divider_rows) >= 2:
            r0, r1 = divider_rows[0] + 1, divider_rows[1]
        else:
            r0, r1 = 0, divider_rows[0]
    else:
        r0, r1 = 0, h

